/**
 * S19 — Institutional Trade Telemetry, Position Intelligence & Continuous Learning Loop
 *
 * Every QDE decision, execution event, position snapshot, and trade outcome is
 * persisted here so that signalium-trainer can consume it as structured training
 * material. Nothing generated by the QDE may disappear.
 */

import {
  pgTable,
  text,
  serial,
  timestamp,
  integer,
  real,
  boolean,
  jsonb,
  index,
  uniqueIndex,
} from "drizzle-orm/pg-core";
import { opportunitiesTable } from "./inference";
import { positionTelemetryTable } from "./qde";

// ─── 1. QDE Decisions ────────────────────────────────────────────────────────
// One row per inference call. Every decision produced by the QDE is persisted.

export const qdeDecisionsTable = pgTable(
  "qde_decisions",
  {
    id: serial("id").primaryKey(),
    decisionId: text("decision_id").notNull(), // uuid — stable identifier forwarded to trainer
    modelVersion: text("model_version"),
    symbol: text("symbol").notNull(),
    userId: text("user_id").notNull(),
    opportunityId: integer("opportunity_id").references(() => opportunitiesTable.id, { onDelete: "set null" }),
    telemetryId: integer("telemetry_id").references(() => positionTelemetryTable.id, { onDelete: "set null" }),
    // Inference type: inference | review-position | manual-analysis | portfolio-review | reasoning
    inferenceType: text("inference_type").notNull().default("inference"),
    direction: text("direction"),   // "LONG" | "SHORT" | "NEUTRAL"
    confidence: real("confidence"), // 0–1
    riskSignal: text("risk_signal"),
    sizeSignal: text("size_signal"),
    entryUrgency: text("entry_urgency"),
    exitHorizon: text("exit_horizon"),
    session: text("session"),             // "LONDON" | "NEW_YORK" | "ASIAN" | "OVERLAP"
    volatilityState: text("volatility_state"), // "LOW" | "MODERATE" | "HIGH" | "EXTREME"
    spreadState: text("spread_state"),    // "TIGHT" | "NORMAL" | "WIDE"
    trainerOnline: boolean("trainer_online").notNull().default(false),
    /** S21B — deployment traceability: which model artifact produced this decision. */
    artifactHash: text("artifact_hash"),
    manifestHash: text("manifest_hash"),
    featureVersion: text("feature_version"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("qde_decisions_user_idx").on(t.userId),
    index("qde_decisions_symbol_idx").on(t.symbol),
    index("qde_decisions_opportunity_idx").on(t.opportunityId),
    index("qde_decisions_created_at_idx").on(t.createdAt),
  ],
);

export type QdeDecision = typeof qdeDecisionsTable.$inferSelect;

// ─── 2. Decision Reasoning ───────────────────────────────────────────────────
// Detailed reasoning text and structured pattern classification per decision.

export const decisionReasoningTable = pgTable("decision_reasoning", {
  id: serial("id").primaryKey(),
  decisionId: integer("decision_id").notNull().references(() => qdeDecisionsTable.id, { onDelete: "cascade" }),
  reasoning: text("reasoning").notNull(),
  primaryPattern: text("primary_pattern"), // "trend_continuation" | "breakout" | "reversal" | etc.
  supportingFactors: text("supporting_factors").array(),
  contradictingFactors: text("contradicting_factors").array(),
  warnings: text("warnings").array(),
  rawModelOutput: jsonb("raw_model_output"),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export type DecisionReasoning = typeof decisionReasoningTable.$inferSelect;

// ─── 3. Decision Context ─────────────────────────────────────────────────────
// Market snapshot present at the moment of the decision.

export const decisionContextTable = pgTable("decision_context", {
  id: serial("id").primaryKey(),
  decisionId: integer("decision_id").notNull().references(() => qdeDecisionsTable.id, { onDelete: "cascade" }),
  balance: real("balance"),
  equity: real("equity"),
  margin: real("margin"),
  freeMargin: real("free_margin"),
  openPositions: integer("open_positions"),
  floatingPnl: real("floating_pnl"),
  entryPrice: real("entry_price"),
  currentPrice: real("current_price"),
  spread: real("spread"),
  drawdown: real("drawdown"),
  tradeAgeSeconds: integer("trade_age_seconds"),
  // Derived market quality fields (populated from available data or trainer response)
  trendStrength: real("trend_strength"),   // 0–1
  volatility: real("volatility"),          // annualised or relative
  marketQuality: text("market_quality"),   // "EXCELLENT" | "GOOD" | "FAIR" | "POOR"
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export type DecisionContext = typeof decisionContextTable.$inferSelect;

// ─── 4. Execution Telemetry ──────────────────────────────────────────────────
// EA-reported execution quality per fill. Sent as an optional `execution` block
// inside the standard telemetry frame so no extra EA request is needed.

export const executionTelemetryTable = pgTable(
  "execution_telemetry",
  {
    id: serial("id").primaryKey(),
    userId: text("user_id").notNull(),
    symbol: text("symbol").notNull(),
    opportunityId: integer("opportunity_id").references(() => opportunitiesTable.id, { onDelete: "set null" }),
    telemetryId: integer("telemetry_id").references(() => positionTelemetryTable.id, { onDelete: "set null" }),
    requestedEntry: real("requested_entry"),
    actualEntry: real("actual_entry"),
    slippage: real("slippage"),           // actualEntry - requestedEntry (positive = adverse)
    spread: real("spread"),               // spread at time of execution (pips/points)
    commission: real("commission"),       // absolute value, negative means cost
    executionDelayMs: integer("execution_delay_ms"),
    partialFill: boolean("partial_fill").notNull().default(false),
    requotes: integer("requotes").notNull().default(0),
    session: text("session"),
    volatilityState: text("volatility_state"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("execution_telemetry_user_idx").on(t.userId),
    index("execution_telemetry_symbol_idx").on(t.symbol),
    index("execution_telemetry_created_at_idx").on(t.createdAt),
  ],
);

export type ExecutionTelemetry = typeof executionTelemetryTable.$inferSelect;

// ─── 5. Execution Quality Metrics ────────────────────────────────────────────
// Aggregated execution stats per symbol × session × volatility bucket.
// Upserted after every N new execution_telemetry rows for a given segment.

export const executionQualityMetricsTable = pgTable(
  "execution_quality_metrics",
  {
    id: serial("id").primaryKey(),
    symbol: text("symbol").notNull(),
    session: text("session").notNull(),
    volatilityState: text("volatility_state").notNull(),
    avgSlippage: real("avg_slippage"),
    avgSpread: real("avg_spread"),
    avgCommission: real("avg_commission"),
    avgExecutionDelayMs: real("avg_execution_delay_ms"),
    partialFillRate: real("partial_fill_rate"), // 0–1
    requoteRate: real("requote_rate"),           // avg requotes per execution
    sampleCount: integer("sample_count").notNull().default(0),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex("execution_quality_segment_unique").on(t.symbol, t.session, t.volatilityState),
  ],
);

export type ExecutionQualityMetrics = typeof executionQualityMetricsTable.$inferSelect;

// ─── 6. Position Snapshots ───────────────────────────────────────────────────
// Full P/L + distance + margin snapshot taken on every polling cycle.
// This becomes the trade memory stream.

export const positionSnapshotsTable = pgTable(
  "position_snapshots",
  {
    id: serial("id").primaryKey(),
    userId: text("user_id").notNull(),
    symbol: text("symbol").notNull(),
    opportunityId: integer("opportunity_id").references(() => opportunitiesTable.id, { onDelete: "set null" }),
    telemetryId: integer("telemetry_id").references(() => positionTelemetryTable.id, { onDelete: "set null" }),
    profit: real("profit"),             // floating P/L in account currency
    drawdown: real("drawdown"),         // current drawdown %
    swap: real("swap"),
    commission: real("commission"),
    equityImpact: real("equity_impact"), // floatingPnl / equity * 100
    distanceToStop: real("distance_to_stop"),     // pips/points to SL
    distanceToTarget: real("distance_to_target"), // pips/points to TP
    marginUsage: real("margin_usage"),            // margin / balance * 100
    positionAgeSeconds: integer("position_age_seconds"),
    confidence: real("confidence"),               // QDE confidence at this moment
    snapshotAt: timestamp("snapshot_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("position_snapshots_opportunity_idx").on(t.opportunityId),
    index("position_snapshots_user_idx").on(t.userId),
    index("position_snapshots_snapshot_at_idx").on(t.snapshotAt),
  ],
);

export type PositionSnapshot = typeof positionSnapshotsTable.$inferSelect;

// ─── 7. Position Metrics ─────────────────────────────────────────────────────
// Aggregated per-opportunity metrics: MFE, MAE, confidence series.
// Upserted on every snapshot.

export const positionMetricsTable = pgTable(
  "position_metrics",
  {
    id: serial("id").primaryKey(),
    userId: text("user_id").notNull(),
    symbol: text("symbol").notNull(),
    opportunityId: integer("opportunity_id").notNull().references(() => opportunitiesTable.id, { onDelete: "cascade" }),
    mfe: real("mfe"),               // Maximum Favorable Excursion (account currency)
    mae: real("mae"),               // Maximum Adverse Excursion (account currency, positive value)
    mfeR: real("mfe_r"),           // MFE expressed in R-multiples (MFE / initial risk)
    maeR: real("mae_r"),           // MAE expressed in R-multiples
    peakProfit: real("peak_profit"),
    maxDrawdown: real("max_drawdown"),
    entryConfidence: real("entry_confidence"),
    peakConfidence: real("peak_confidence"),
    minConfidence: real("min_confidence"),
    confidenceVolatility: real("confidence_volatility"), // std-dev of confidence series
    confidenceSlope: real("confidence_slope"),           // linear regression slope
    confidenceSeries: real("confidence_series").array(), // time series of confidence readings
    snapshotCount: integer("snapshot_count").notNull().default(0),
    breakevenHitAt: timestamp("breakeven_hit_at", { withTimezone: true }),
    scaleInCount: integer("scale_in_count").notNull().default(0),
    partialCloseCount: integer("partial_close_count").notNull().default(0),
    trailingEfficiency: real("trailing_efficiency"), // % of peak profit captured at exit
    exitEfficiency: real("exit_efficiency"),         // actualExit / theoreticalBestExit
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex("position_metrics_opportunity_unique").on(t.opportunityId),
  ],
);

export type PositionMetrics = typeof positionMetricsTable.$inferSelect;

// ─── 8. Trade Events ─────────────────────────────────────────────────────────
// Individual events in a trade's lifecycle. The complete sequence is stored.

export const tradeEventsTable = pgTable(
  "trade_events",
  {
    id: serial("id").primaryKey(),
    userId: text("user_id").notNull(),
    symbol: text("symbol").notNull(),
    opportunityId: integer("opportunity_id").notNull().references(() => opportunitiesTable.id, { onDelete: "cascade" }),
    eventType: text("event_type").notNull(),
    // e.g. "setup_detected" | "confidence_rising" | "entry" | "confidence_drop"
    //      | "stop_moved" | "scale_in" | "partial_close" | "breakeven_hit"
    //      | "momentum_weakens" | "exit" | "state_transition" | "decision"
    confidence: real("confidence"),
    price: real("price"),
    note: text("note"),
    metadata: jsonb("metadata"),
    occurredAt: timestamp("occurred_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("trade_events_opportunity_idx").on(t.opportunityId),
    index("trade_events_occurred_at_idx").on(t.occurredAt),
  ],
);

export type TradeEvent = typeof tradeEventsTable.$inferSelect;

// ─── 9. Trade Timeline ───────────────────────────────────────────────────────
// Trade-level summary record created when a position reaches EXITED state.

export const tradeTimelineTable = pgTable(
  "trade_timeline",
  {
    id: serial("id").primaryKey(),
    userId: text("user_id").notNull(),
    symbol: text("symbol").notNull(),
    opportunityId: integer("opportunity_id").notNull().references(() => opportunitiesTable.id, { onDelete: "cascade" }),
    entryAt: timestamp("entry_at", { withTimezone: true }),
    exitAt: timestamp("exit_at", { withTimezone: true }),
    entryPrice: real("entry_price"),
    exitPrice: real("exit_price"),
    stopLoss: real("stop_loss"),
    takeProfit: real("take_profit"),
    direction: text("direction"),   // "LONG" | "SHORT"
    finalPnl: real("final_pnl"),    // in account currency
    rMultiple: real("r_multiple"),  // finalPnl / initial risk (null if risk unknown)
    outcome: text("outcome"),       // "win" | "loss" | "breakeven"
    setupType: text("setup_type"),  // primary pattern at entry
    session: text("session"),
    modelVersion: text("model_version"),
    totalEvents: integer("total_events").notNull().default(0),
    durationSeconds: integer("duration_seconds"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex("trade_timeline_opportunity_unique").on(t.opportunityId),
    index("trade_timeline_user_idx").on(t.userId),
    index("trade_timeline_symbol_idx").on(t.symbol),
    index("trade_timeline_exit_at_idx").on(t.exitAt),
  ],
);

export type TradeTimeline = typeof tradeTimelineTable.$inferSelect;

// ─── 10. Reasoning Validation ────────────────────────────────────────────────
// Post-trade record of whether the initial reasoning was correct.

export const reasoningValidationTable = pgTable(
  "reasoning_validation",
  {
    id: serial("id").primaryKey(),
    userId: text("user_id").notNull(),
    symbol: text("symbol").notNull(),
    opportunityId: integer("opportunity_id").notNull().references(() => opportunitiesTable.id, { onDelete: "cascade" }),
    decisionId: integer("decision_id").references(() => qdeDecisionsTable.id, { onDelete: "set null" }),
    initialReasoning: text("initial_reasoning"),
    initialPattern: text("initial_pattern"),
    wasCorrect: boolean("was_correct"),
    actualPattern: text("actual_pattern"),   // what actually drove the move
    correctnessScore: real("correctness_score"), // 0–1 partial credit
    validatorNote: text("validator_note"),
    validatedAt: timestamp("validated_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex("reasoning_validation_opportunity_unique").on(t.opportunityId),
  ],
);

export type ReasoningValidation = typeof reasoningValidationTable.$inferSelect;

// ─── 11. Reasoning Accuracy ──────────────────────────────────────────────────
// Rolling accuracy stats per pattern × symbol × session.
// Upserted after every reasoning_validation insert.

export const reasoningAccuracyTable = pgTable(
  "reasoning_accuracy",
  {
    id: serial("id").primaryKey(),
    pattern: text("pattern").notNull(),
    symbol: text("symbol").notNull().default("*"), // "*" = across all symbols
    session: text("session").notNull().default("*"),
    totalPredictions: integer("total_predictions").notNull().default(0),
    correctPredictions: integer("correct_predictions").notNull().default(0),
    accuracyRate: real("accuracy_rate"),           // correct / total
    avgConfidenceWhenCorrect: real("avg_confidence_when_correct"),
    avgConfidenceWhenWrong: real("avg_confidence_when_wrong"),
    lastUpdatedAt: timestamp("last_updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex("reasoning_accuracy_segment_unique").on(t.pattern, t.symbol, t.session),
  ],
);

export type ReasoningAccuracy = typeof reasoningAccuracyTable.$inferSelect;

// ─── 12. Trade Failures ──────────────────────────────────────────────────────
// Every loss > 1R triggers an investigation record.

export const tradeFailuresTable = pgTable(
  "trade_failures",
  {
    id: serial("id").primaryKey(),
    userId: text("user_id").notNull(),
    symbol: text("symbol").notNull(),
    opportunityId: integer("opportunity_id").notNull().references(() => opportunitiesTable.id, { onDelete: "cascade" }),
    rootCause: text("root_cause"),
    warningSigns: text("warning_signs").array(),
    confidenceDecayNotes: text("confidence_decay_notes"),
    lateExitIndicators: text("late_exit_indicators").array(),
    positionManagementIssues: text("position_management_issues").array(),
    finalLoss: real("final_loss"),                // absolute loss in account currency
    maxAdverseExcursion: real("max_adverse_excursion"),
    adminNotes: text("admin_notes"),
    investigatedAt: timestamp("investigated_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex("trade_failures_opportunity_unique").on(t.opportunityId),
    index("trade_failures_symbol_idx").on(t.symbol),
  ],
);

export type TradeFailure = typeof tradeFailuresTable.$inferSelect;

// ─── 13. Failure Patterns ────────────────────────────────────────────────────
// Recurring failure pattern aggregation across many trades.

export const failurePatternsTable = pgTable(
  "failure_patterns",
  {
    id: serial("id").primaryKey(),
    patternType: text("pattern_type").notNull(),
    // e.g. "late_exit" | "early_stop" | "overconfidence" | "bad_session_timing"
    //      | "spread_spikes" | "correlation_risk" | "news_timing"
    symbol: text("symbol").notNull().default("*"),
    session: text("session").notNull().default("*"),
    occurrences: integer("occurrences").notNull().default(0),
    avgLoss: real("avg_loss"),
    description: text("description"),
    firstSeenAt: timestamp("first_seen_at", { withTimezone: true }).notNull().defaultNow(),
    lastSeenAt: timestamp("last_seen_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex("failure_patterns_segment_unique").on(t.patternType, t.symbol, t.session),
  ],
);

export type FailurePattern = typeof failurePatternsTable.$inferSelect;

// ─── 14. Counterfactual Results ──────────────────────────────────────────────
// What-if analysis generated for every closed trade.

export const counterfactualResultsTable = pgTable(
  "counterfactual_results",
  {
    id: serial("id").primaryKey(),
    opportunityId: integer("opportunity_id").notNull().references(() => opportunitiesTable.id, { onDelete: "cascade" }),
    userId: text("user_id").notNull(),
    symbol: text("symbol").notNull(),
    scenarioType: text("scenario_type").notNull(),
    // "wider_stop" | "smaller_size" | "earlier_exit" | "no_scale_in"
    parameterDescription: text("parameter_description"),
    baselinePnl: real("baseline_pnl"),          // actual result
    counterfactualPnl: real("counterfactual_pnl"), // estimated result under scenario
    improvement: real("improvement"),            // counterfactualPnl - baselinePnl
    improvementPct: real("improvement_pct"),
    analysis: text("analysis"),                 // narrative explanation
    generatedAt: timestamp("generated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex("counterfactual_opportunity_scenario_unique").on(t.opportunityId, t.scenarioType),
    index("counterfactual_user_idx").on(t.userId),
  ],
);

export type CounterfactualResult = typeof counterfactualResultsTable.$inferSelect;

// ─── 15. Learning Candidates ─────────────────────────────────────────────────
// High-value trade examples prioritised for the trainer to consume first.

export const learningCandidatesTable = pgTable(
  "learning_candidates",
  {
    id: serial("id").primaryKey(),
    opportunityId: integer("opportunity_id").notNull().references(() => opportunitiesTable.id, { onDelete: "cascade" }),
    userId: text("user_id").notNull(),
    symbol: text("symbol").notNull(),
    candidateType: text("candidate_type").notNull(),
    // "large_loss" | "large_win" | "unexpected_reversal" | "high_confidence_failure"
    // | "perfect_execution" | "regime_edge_case" | "exceptional_management"
    priority: integer("priority").notNull().default(0), // higher = consumed first
    pnl: real("pnl"),
    rMultiple: real("r_multiple"),
    notes: text("notes"),
    processedByTrainer: boolean("processed_by_trainer").notNull().default(false),
    processedAt: timestamp("processed_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    uniqueIndex("learning_candidates_opportunity_type_unique").on(t.opportunityId, t.candidateType),
    index("learning_candidates_priority_idx").on(t.priority),
    index("learning_candidates_processed_idx").on(t.processedByTrainer),
  ],
);

export type LearningCandidate = typeof learningCandidatesTable.$inferSelect;

// ─── 16. Self-Evaluation Reports ─────────────────────────────────────────────
// Auto-generated daily / weekly / monthly performance reviews.

export const selfEvaluationReportsTable = pgTable(
  "self_evaluation_reports",
  {
    id: serial("id").primaryKey(),
    reportType: text("report_type").notNull(), // "daily" | "weekly" | "monthly"
    periodStart: timestamp("period_start", { withTimezone: true }).notNull(),
    periodEnd: timestamp("period_end", { withTimezone: true }).notNull(),
    totalTrades: integer("total_trades").notNull().default(0),
    wins: integer("wins").notNull().default(0),
    losses: integer("losses").notNull().default(0),
    winRate: real("win_rate"),         // wins / totalTrades
    avgRMultiple: real("avg_r_multiple"),
    bestRMultiple: real("best_r_multiple"),
    worstRMultiple: real("worst_r_multiple"),
    sharpeRatio: real("sharpe_ratio"),
    bestSymbol: text("best_symbol"),
    worstSymbol: text("worst_symbol"),
    bestSession: text("best_session"),
    worstSession: text("worst_session"),
    confidenceReliability: real("confidence_reliability"), // correlation: high conf → win
    reasoningAccuracy: real("reasoning_accuracy"),
    modelQualityScore: real("model_quality_score"),        // composite 0–1
    insights: text("insights").array(),
    rawData: jsonb("raw_data"),
    generatedAt: timestamp("generated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    index("self_eval_reports_type_period_idx").on(t.reportType, t.periodEnd),
  ],
);

export type SelfEvaluationReport = typeof selfEvaluationReportsTable.$inferSelect;

// ─── Trainer sync state ──────────────────────────────────────────────────────
// Singleton row tracking the last successful batch sync to signalium-trainer.

export const trainerSyncStateTable = pgTable("trainer_sync_state", {
  id: text("id").primaryKey(), // always "global"
  lastSyncAt: timestamp("last_sync_at", { withTimezone: true }),
  lastSyncStatus: text("last_sync_status"), // "ok" | "error" | "partial"
  lastSyncMessage: text("last_sync_message"),
  decisionsExported: integer("decisions_exported").notNull().default(0),
  timelinesExported: integer("timelines_exported").notNull().default(0),
  executionsExported: integer("executions_exported").notNull().default(0),
  candidatesExported: integer("candidates_exported").notNull().default(0),
  totalSyncs: integer("total_syncs").notNull().default(0),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

export type TrainerSyncState = typeof trainerSyncStateTable.$inferSelect;
